import {business,options,categoryDetails} from './business.js';
export const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
export const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const link=(text,url,outline=false)=>`<a class="button ${outline?'outline':''}" href="${escape(url)}">${text}</a>`;
const heading=(k,h,p='')=>`<div class="page-title"><span class="eyebrow">${k}</span><h1>${h}</h1>${p?`<p>${p}</p>`:''}</div>`;
export const services=[
 {slug:'airport-transfers',name:'Airport Transfers',lead:'Your journey starts before takeoff.',intro:'ATL arrivals and departures, thoughtfully arranged around your travel plans.',body:'Choose a sedan, SUV or Sprinter transfer, then select your appointment in our live booking calendar. Keep your flight number, pickup details and luggage requirements ready so your airport journey can be coordinated.',details:['Choose arrival or departure','Share flight and pickup details','Confirm vehicle capacity and arrangements']},
 {slug:'hourly-chauffeur',name:'Hourly Chauffeur',lead:'Time, on your terms.',intro:'Reserve time for your plans, with a choice of three luxury vehicle categories.',body:'Our supplied hourly listings offer one-hour appointments for the Luxury Sedan, Luxury SUV and Luxury Sprinter. For additional time, multiple stops or a tailored itinerary, contact us before booking so the right arrangements can be made.',details:['Select your vehicle category','Discuss your itinerary and stops','Confirm any additional time']},
 {slug:'corporate-travel',name:'Corporate Travel',lead:'Business, with breathing room.',intro:'Considered transportation for meetings, conferences and client visits.',body:'Martinez Logistics offers corporate travel and executive transportation. Share your schedule, pickup locations and passenger needs to discuss arrangements for your business journey. Ask about billing and account arrangements when planning regular travel.',details:['Meetings and client visits','Conference transportation','Tailored travel arrangements']},
 {slug:'executive-transportation',name:'Executive Transportation',lead:'Arrive with intention.',intro:'A professional chauffeur experience for executives and private travel.',body:'Bring the details of your day together with a chauffeur journey arranged around your itinerary. Contact Martinez Logistics to discuss timing, vehicle suitability and any specific pickup arrangements before making a reservation.',details:['Personal travel arrangements','Considered pickup coordination','A vehicle category for your plans']},
 {slug:'special-events',name:'Special Events',lead:'Let the occasion lead.',intro:'Plan the journey as carefully as the occasion.',body:'The company offers transportation for special events. Share your venue, timing, party size and return plans to discuss the service and vehicle category that suit your occasion. Event charters require individual confirmation.',details:['Venue and arrival coordination','Passenger and luggage planning','Individual event arrangements']}
];
export const faqs=[
 ['How do I book?','Select a vehicle and service, then open the live Acuity calendar. Available times, passenger details and final confirmation are handled by the company’s booking system.'],
 ['Can I book an ATL airport transfer?','Yes. The booking menu includes ATL arrival and departure transfers for Sedan, SUV and Sprinter categories. Select the appropriate direction when booking.'],
 ['What are the listed rates?','Hourly one-hour listings are $165 for Luxury Sedan, $197 for Luxury SUV and $550 for Luxury Sprinter. ATL transfer listings vary by category and direction; the full service menu shows all nine options.'],
 ['What information do I need for pickup?','Have your date and time, pickup and destination, passenger and luggage counts, and any flight details ready. Confirm any special pickup requirements with the company.'],
 ['Can I choose a specific make or model?','Vehicle categories are available to select. Confirm the exact vehicle model, seating, luggage capacity and amenities with the company before booking.'],
 ['How do I arrange additional stops or time?','Contact the company with your itinerary before booking. Additional time, stops and any associated charges require confirmation.'],
 ['What are the cancellation and payment terms?','Review the terms presented in the live booking system and confirm any questions with the company before completing your reservation. No cancellation fees or deposits are specified on this site.'],
 ['Can you accommodate child seating or accessibility needs?','Email your requirements before booking. Availability and suitability need to be confirmed for your journey.']
];
export const routeMeta={
 '/':['Martinez Logistics LLC | The Art of Arriving','Luxury chauffeur service, ATL airport transfers, corporate travel and hourly sedan, SUV and Sprinter options.'],
 '/fleet':['Our Fleet | Martinez Logistics LLC','Explore Luxury Sedan, SUV and Sprinter chauffeur categories and choose your service.'],
 '/services':['Chauffeur Services | Martinez Logistics LLC','Discover ATL airport transfers, hourly chauffeur, corporate travel, executive transportation and special events.'],
 '/about':['Our Story | Martinez Logistics LLC','From logistics in 2016 to luxury chauffeur service in 2025. Discover Martinez Logistics LLC.'],
 '/service-areas':['ATL Airport Transportation | Martinez Logistics LLC','Explore ATL arrival and departure chauffeur transfer options.'],
 '/contact':['Contact | Martinez Logistics LLC','Contact Martinez Logistics LLC to discuss your journey or reserve through the live booking calendar.'],
 '/faq':['Frequently Asked Questions | Martinez Logistics LLC','Answers about vehicle categories, rates, ATL transfers and making a chauffeur reservation.'],
 '/reserve':['Reserve Your Ride | Martinez Logistics LLC','Choose from nine chauffeur service options and reserve with the live Acuity booking system.'],
 '/privacy':['Privacy | Martinez Logistics LLC','How this website links to the booking provider and handles contact information.'],
 '/terms':['Booking Information | Martinez Logistics LLC','Important information about service listings, pricing and booking confirmation.']
};
for(const s of services)routeMeta['/services/'+s.slug]=[`${s.name} | Martinez Logistics LLC`,s.intro];
for(const c of Object.keys(categoryDetails))routeMeta['/fleet/'+c.toLowerCase()]=[`Luxury ${c} | Martinez Logistics LLC`,categoryDetails[c].description];
export function rateTable(filter=()=>true){return `<div class="rate-wrap"><table class="rate-table"><caption class="sr-only">Available chauffeur service options and one-hour listing rates</caption><thead><tr><th scope="col">SERVICE</th><th scope="col">1-HOUR LISTING</th><th scope="col"><span class="sr-only">Reservation</span></th></tr></thead><tbody>${options.map((o,i)=>({o,i})).filter(({o})=>filter(o)).map(({o,i})=>`<tr><th scope="row">${o.name}</th><td>${money(o.price)}</td><td>${link('Select',`/reserve/?option=${i}`)}</td></tr>`).join('')}</tbody></table></div><p class="caption">Rates reflect the listed one-hour appointments. Review final pricing, availability and applicable terms in the live booking system.</p>`}
const cta=()=>`<section class="final-cta"><span class="eyebrow">THE NEXT CHAPTER</span><h2>Your next arrival<br>begins here.</h2><p>Choose your service. Find your time. Make your arrival.</p>${link('Reserve Your Ride','/reserve/')}</section>`;
const faqList=()=>`<div class="faq">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
export function home(){return `<section class="hero"><div class="cinematic-light" aria-hidden="true"></div><div class="entrance"><span class="eyebrow">MARTINEZ LOGISTICS LLC · CHAUFFEUR SERVICE</span><h1>The Art<br>of <em>Arriving.</em></h1><p>Professional chauffeur transportation,<br>thoughtfully arranged around your journey.</p><div class="actions">${link('Reserve Your Ride','/reserve/')}${link('Explore Our Fleet','/fleet/',true)}</div></div><div class="hero-bottom"><span><b>01 —</b> &nbsp; EVERY JOURNEY DESERVES AN ENTRANCE</span><a href="#introduction">DISCOVER MORE</a></div><button class="skip-intro" type="button" hidden>Skip entrance</button></section><section class="intro" id="introduction"><div><span class="eyebrow">A MORE CONSIDERED WAY TO TRAVEL</span><h2>Transportation,<br><em>Elevated.</em></h2></div><div><p>From the airport to the next appointment, the journey deserves the same consideration as the destination. Martinez Logistics brings its roots in dependable transportation to a more personal chauffeur experience.</p><a class="text-link" href="/about/">Discover Martinez</a><p class="caption">Editorial hero imagery is illustrative, rather than a photograph of the company’s fleet.</p></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">THE COLLECTION</span><h2>A class for every arrival.</h2></div><a class="text-link" href="/fleet/">Enter the private showroom</a></div><div class="fleet-grid">${options.slice(0,3).map((o,i)=>`<a class="fleet-card" href="/fleet/${o.category.toLowerCase()}/"><span class="number">0${i+1} / THE COLLECTION</span><h3>${o.name}</h3><div class="price">${money(o.price)} <small>/ one-hour listing</small></div><span class="card-label">Explore ${o.category}</span></a>`).join('')}</div></section><section class="section"><span class="eyebrow">AT YOUR SERVICE</span><h2>Your journey. Your pace.</h2>${services.slice(0,4).map((s,i)=>`<a class="service-row" href="/services/${s.slug}/"><span class="num">0${i+1}</span><h3>${s.name}</h3><p>${s.intro}</p></a>`).join('')}</section><section class="experience section"><span class="eyebrow">THE CHAUFFEUR EXPERIENCE</span><h2>A little more thought.<br>A different kind of journey.</h2><div class="steps">${[['01','Before you travel','Choose the service and category that fit your plans. Share the timing and details that make your journey yours.'],['02','Along the way','Professional chauffeur transportation creates space for your next meeting, your next destination or simply your own time.'],['03','At your arrival','From business travel to a special occasion, arrange your arrival with the same care as the rest of your day.']].map(a=>`<div><b>${a[0]}</b><h3>${a[1]}</h3><p>${a[2]}</p></div>`).join('')}</div></section><section class="section airport-feature"><div><span class="eyebrow">ATL ARRIVALS & DEPARTURES</span><h2>From curbside<br>to what comes next.</h2><p>Arrange an airport arrival or departure with a dedicated listing for your selected vehicle category.</p>${link('Explore Airport Transfers','/services/airport-transfers/',true)}</div><div class="airport-routes"><span>ATL</span><p>ARRIVALS / DEPARTURES</p><div>Sedan <span>from ${money(120)}</span></div><div>SUV <span>from ${money(180)}</span></div><div>Sprinter <span>${money(400)}</span></div></div></section><section class="section"><span class="eyebrow">A SEAMLESS START</span><h2>Make it your journey.</h2><div class="steps">${[['01','Choose your service','Explore the collection and select the hourly or ATL transfer listing that fits your plans.'],['02','Find your time','Open the company’s live Acuity calendar and choose an available appointment.'],['03','Complete your reservation','Enter the requested details and review the booking system’s pricing and confirmation.']].map(a=>`<div><b>${a[0]}</b><h3>${a[1]}</h3><p>${a[2]}</p></div>`).join('')}</div></section>${cta()}`}
export function fleet(path){const category=Object.keys(categoryDetails).find(c=>path.endsWith('/'+c.toLowerCase()))||'Sedan';return `<div class="page showroom-page">${heading('THE PRIVATE SHOWROOM','A considered collection.','Three categories. One considered chauffeur experience.')}<section class="showroom immersive" aria-label="Fleet category presentation"><div class="showroom-stage" data-category="${category}"><div class="stage-word" aria-hidden="true">${category.toUpperCase()}</div><div class="stage-floor" aria-hidden="true"></div><div class="stage-content"></div><p class="stage-caption caption"></p></div><div class="showroom-details"><span class="eyebrow">EXPLORE THE COLLECTION</span><div class="selector" role="group" aria-label="Vehicle category">${Object.keys(categoryDetails).map(c=>`<button data-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div id="vehicle" aria-live="polite"><h2>Luxury ${category}</h2><h3>${categoryDetails[category].headline}</h3><p>${categoryDetails[category].description}</p>${link('Select This Category',`/reserve/?option=${Object.keys(categoryDetails).indexOf(category)}`)}</div><div class="stage-controls"><button type="button" id="previous-category">Previous category</button><span id="category-count"></span><button type="button" id="next-category">Next category</button></div><p class="caption">Exact vehicle model, seating, luggage capacity and amenities are confirmed when arranging your journey.</p></div></section><section class="category-rates"><span class="eyebrow">THE SERVICE MENU</span><h2>Find your journey.</h2><div id="category-rates">${rateTable(o=>o.category===category)}</div></section></div>${cta()}`}
export function booking(){return `<div class="page reservation-page">${heading('PRIVATE RESERVATIONS','Your journey awaits.','Select a service to see live appointment availability.')}<div class="live-booking"><aside><span class="eyebrow">01 / YOUR SERVICE</span><label for="booking-service">Choose your service</label><select id="booking-service" aria-label="Choose your service">${options.map((o,i)=>`<option value="${i}">${o.name} — ${money(o.price)}</option>`).join('')}</select><div id="booking-selection" aria-live="polite"></div><div class="booking-guide"><h3>Before you book.</h3><p>Have your pickup, destination, flight details and passenger requirements ready.</p><p>Appointments and confirmation are handled securely by Acuity Scheduling. Review the provider’s timezone, final price and terms before completing your reservation.</p></div><a id="external-booking" class="text-link" href="${business.bookingUrl}" target="_blank" rel="noopener noreferrer">Open booking in a new tab</a><p class="caption">Your selected service opens directly. We do not collect card details on this website.</p><a class="text-link" href="/contact/">Questions about your journey?</a></aside><section class="scheduler-panel"><span class="eyebrow">02 / AVAILABILITY & RESERVATION</span><p class="caption" id="scheduler-status" role="status">Loading the company’s live calendar…</p><iframe id="live-scheduler" title="Martinez Logistics live Acuity reservation calendar" referrerpolicy="strict-origin-when-cross-origin" allow="payment" src="${options[0].bookingUrl}"></iframe><noscript><p>Choose your service in the <a href="${business.bookingUrl}">official appointment system</a>.</p></noscript></section></div></div>`}
export function servicePage(path){const s=services.find(x=>path==='/services/'+x.slug);if(!s)return `<div class="page">${heading('SIGNATURE SERVICES','Arranged around you.','A considered journey, for the moments that matter.')}<div class="service-directory">${services.map((s,i)=>`<article><span class="eyebrow">0${i+1}</span><h2>${s.name}</h2><p>${s.intro}</p><a class="text-link" href="/services/${s.slug}/">Explore service</a></article>`).join('')}</div></div>${cta()}`;return `<div class="page">${heading(s.name,s.lead,s.intro)}<div class="intro service-intro"><div><h2>Consider the<br>journey taken care of.</h2></div><div><p>${s.body}</p>${link(s.slug==='airport-transfers'||s.slug==='hourly-chauffeur'?'Choose Your Service':'Discuss Your Journey',s.slug==='airport-transfers'||s.slug==='hourly-chauffeur'?'/reserve/':'/contact/')}</div></div><div class="steps service-details">${s.details.map((d,i)=>`<div><b>0${i+1}</b><h3>${d}</h3></div>`).join('')}</div>${s.slug==='airport-transfers'||s.slug==='hourly-chauffeur'?rateTable(o=>s.slug==='airport-transfers'?o.type!=='Hourly':o.type==='Hourly'):`<section class="section"><h2>Choose your category.</h2><p>Explore Sedan, SUV and Sprinter options. Corporate and event itineraries require individual confirmation.</p>${link('Explore the Collection','/fleet/',true)}</section>`}<section class="section"><span class="eyebrow">USEFUL DETAILS</span>${faqList()}</section></div>${cta()}`}
export function contact(){return `<div class="page">${heading('GET IN TOUCH','Let’s arrange<br>your arrival.','A special itinerary. A question before booking. A detail that matters.')}<div class="contact-layout"><div><span class="eyebrow">DIRECT CONTACT</span><a class="contact-email" href="mailto:${business.email}">${business.email.toLowerCase()}</a><p>For additional stops, extended time, corporate arrangements or special requests, share your plans before reserving.</p><a class="text-link" href="${business.bookingUrl}">Visit the official booking page</a></div><form id="contact-form"><label>Your name<input name="name" autocomplete="name" maxlength="120" required></label><label>Your email<input name="email" autocomplete="email" type="email" maxlength="200" required></label><label>How can we help?<textarea name="message" maxlength="4000" required></textarea></label><p class="caption">This opens a message in your email app for you to review and send. It does not submit a message automatically.</p><button class="button" type="submit">Compose Email</button><p role="status" id="contact-status" class="caption"></p></form></div></div>${cta()}`}
export function about(){return `<div class="page">${heading('OUR STORY','Built on the journey.','A transportation story, with a considered new chapter.')}<section class="story-timeline"><article><span class="eyebrow">2016 / THE BEGINNING</span><h2>Dependability,<br>from day one.</h2><p>Martinez Logistics LLC began in 2016 with a 26-foot box truck, providing pickups and deliveries for businesses. Reliability, careful handling and customer service shaped the company’s approach to transportation.</p></article><article><span class="eyebrow">2025 / A NEW CHAPTER</span><h2>The move<br>to chauffeur service.</h2><p>In 2025, the company expanded into luxury black car and limousine transportation, bringing its operational experience to corporate clients, special events, airport transfers and executive travel.</p></article></section><section class="section"><span class="eyebrow">THE EXPERIENCE TODAY</span><h2>Considered travel.<br>Personal attention.</h2><p>Explore luxury Sedan, SUV and Sprinter categories, select an ATL transfer or hourly appointment, and arrange the details of your journey with Martinez Logistics.</p>${link('Explore Our Services','/services/',true)}</section></div>${cta()}`}
export function areas(){return `<div class="page">${heading('SERVICE AREAS','An ATL connection.','Your airport journey, in either direction.')}<div class="area-grid"><article><span class="eyebrow">ARRIVALS</span><h2>Welcome<br>to your next chapter.</h2><p>Select an ATL arrival transfer in the Sedan, SUV or Sprinter category. Have your flight and destination details ready for the booking process.</p>${link('Choose an Arrival','/reserve/?option=4')}</article><article><span class="eyebrow">DEPARTURES</span><h2>Start with<br>a considered departure.</h2><p>Choose an ATL departure transfer and arrange your pickup around your travel plans. Confirm the appropriate pickup time and location before travel.</p>${link('Choose a Departure','/reserve/?option=3',true)}</article></div><section class="section"><h2>Beyond the airport.</h2><p>For corporate travel, special events and other itineraries, email your pickup and destination to confirm service availability. We do not publish unverified city coverage.</p>${link('Discuss Your Route','/contact/',true)}</section></div>${cta()}`}
function policy(path){return `<div class="page policy">${path==='/privacy'?heading('PRIVACY','Your information. Your journey.')+`<h2>Browsing this website</h2><p>This website uses no advertising trackers and does not store passenger or payment details. A session flag remembers whether the entrance has played. External font providers and the hosting service may receive standard technical connection data.</p><h2>Making a reservation</h2><p>The reservation page embeds the company’s Acuity Scheduling calendar. When you use that calendar, information is provided directly to the booking provider and the company under the notices and terms displayed there. Your payment details are not handled by this website’s own code.</p><h2>Contacting us</h2><p>The contact form prepares an email in your own email application. It does not send a message or retain a copy on this site. For questions about your information, contact <a href="mailto:${business.email}">${business.email.toLowerCase()}</a>.</p>`:heading('BOOKING INFORMATION','Before your journey.')+`<h2>Service listings and pricing</h2><p>Displayed prices match the one-hour listings in the company’s booking system as checked on October 21, 2026. Current availability, final pricing, payment requirements and any service conditions are shown by the booking provider or confirmed by the company.</p><h2>Reservation confirmation</h2><p>Browsing a category or selecting an appointment here does not itself confirm a reservation. Complete the live booking process and retain the actual confirmation supplied by the booking system.</p><h2>Changes and special requirements</h2><p>Contact the company before booking to confirm special requests, accessibility requirements, child seating, additional time, vehicle capacity or extra stops. Review the cancellation and payment terms presented by the booking provider.</p>`}</div>`}
export function pageContent(path){if(path==='/')return home();if(path.startsWith('/fleet'))return fleet(path);if(path.startsWith('/services'))return servicePage(path);if(path==='/reserve')return booking();if(path==='/contact')return contact();if(path==='/about')return about();if(path==='/service-areas')return areas();if(path==='/faq')return `<div class="page">${heading('FREQUENTLY ASKED','A few useful details.')}${faqList()}</div>${cta()}`;if(path==='/privacy'||path==='/terms')return policy(path);return `<div class="page">${heading('404','A different destination.','This page could not be found.')}${link('Return Home','/')}</div>`}
